            for dr in range(-2, 3):  # Check all positions of (r,c) within 3x3
                for dc in range(-2, 3):
                    win_r, win_c = r - dr, c - dc

                    # Bounds check for 3x3 window
                    if 0 <= win_r < height - 2 and 0 <= win_c < width - 2:
                        # Check all 4 sides of 3x3 window have non-background
