                            if grid[win_r][win_c + dc] == 0:
                                all_sides_bg = False

                        # Bottom row of window
                        for dc in range(3):
                            if grid[win_r + 2][win_c + dc] == 0:
                                all_sides_bg = False

                        # Check left and right columns (top/bottom rows done above)
                        for dr in range(3):
                            if grid[win_r + dr][win_c] == 0:
                                all_sides_bg = False
                            if grid[win_r + dr][win_c + 2] == 0:
                                all_sides_bg = False

